// fade in together (no stagger). At `breakdownDelay`, every candle EXCEPT
// the 5 listed in HIGHLIGHT_IDS fades back out — those 5 are the ones
// FootprintChartAnimated's 5 cell-groups are positioned around (matched by
// real on-chart x-position, not arbitrary), so they stay put permanently
// and become the "middle rectangle" spine of each footprint group, per the
// user's description of how this actually works: the candle itself doesn't
// dissolve away, it's what the footprint cells grow out from beside.
const HIGHLIGHT_IDS = new Set([
  "2999:51503", "2999:51504", // candle+wick near footprint group 3 (leftmost)
  "2999:51518", "2999:51519", // ...group 2
  "2999:51248", "2999:51249", // ...group 5
  "2999:51233", "2999:51234", // ...group 1
  "2999:51224", "2999:51225", // ...group 4 (rightmost)
]);

